package com.daniil.wristlens.phone;
import android.content.Context;import android.graphics.*;import android.net.Uri;import com.daniil.wristlens.core.CopyProfile;import com.daniil.wristlens.shared.Strings;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.io.*;import java.nio.file.Files;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class CopyExporterTest {
 @Test public void photoCopyIsResizedAndOriginalRemainsIdentical()throws Exception{Context c=RuntimeEnvironment.getApplication();Strings.init(c);File input=File.createTempFile("source-",".png",c.getCacheDir());Bitmap b=Bitmap.createBitmap(2560,1440,Bitmap.Config.ARGB_8888);b.eraseColor(0xff285080);Canvas canvas=new Canvas(b);Paint paint=new Paint();paint.setColor(Color.WHITE);canvas.drawRect(0,0,200,200,paint);try(FileOutputStream out=new FileOutputStream(input)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();byte[] source=Files.readAllBytes(input.toPath());MediaFiles.Entry entry=new MediaFiles.Entry("id",Uri.fromFile(input),"IMG.png","image/png",input.length(),0,0);File generated;
  try(var copy=CopyExporter.prepare(c,entry,CopyProfile.of("compact"),()->{})){assertEquals("image/jpeg",copy.mime());assertEquals("IMG_compact.jpg",copy.name());assertTrue(copy.bytes()>0);generated=copy.temporary();Bitmap decoded=BitmapFactory.decodeFile(generated.getAbsolutePath());assertEquals(1280,decoded.getWidth());assertEquals(720,decoded.getHeight());assertTrue(Color.red(decoded.getPixel(10,10))>220);decoded.recycle();assertArrayEquals(source,Files.readAllBytes(input.toPath()));}assertFalse(generated.exists());assertTrue(input.exists());}
 @Test public void originalNeverCreatesOrDeletesADerivative()throws Exception{Context c=RuntimeEnvironment.getApplication();File original=File.createTempFile("original-",".mp4",c.getCacheDir());Files.write(original.toPath(),new byte[]{1,2,3});MediaFiles.Entry e=new MediaFiles.Entry("id",Uri.fromFile(original),"VID.mp4","video/mp4",3,0,0);try(var p=CopyExporter.prepare(c,e,CopyProfile.of("original"),()->{throw new AssertionError();})){assertNull(p.temporary());assertEquals(e.uri(),p.uri());}assertTrue(original.exists());}
 @Test public void requestedBitrateForcesEncodingEvenForH264Input(){Context c=RuntimeEnvironment.getApplication();var factory=CopyExporter.encoder(c,CopyProfile.of("compact"));assertTrue(factory.videoNeedsEncoding());assertTrue(factory.audioNeedsEncoding());}
}
